import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"橫渠易說 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"橫渠易說 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"classics/hengqu/003.md","filePath":"classics/hengqu/003.md"}'),l={name:"classics/hengqu/003.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>乾之四德，終始萬物，迎之不見其首，隨之不見其後，然推本而言，當父母萬物。，彖明萬物資始，故不得不以元配乾；坤其偶也，故不得不以元配坤。天下之理得，元也；會而通，亨也；說諸心，利也；一天下之動，貞也。貞者，專靜也。不曰天地而曰乾坤，言天地則有體，言乾坤則無形，故性也者，雖乾坤亦在其中。</p><h3 id="初九-潛龍勿用。" tabindex="-1">初九，潛龍勿用。 <a class="header-anchor" href="#初九-潛龍勿用。" aria-label="Permalink to “初九，潛龍勿用。”">​</a></h3><h3 id="九二-見龍在田-利見大人。" tabindex="-1">九二，見龍在田，利見大人。 <a class="header-anchor" href="#九二-見龍在田-利見大人。" aria-label="Permalink to “九二，見龍在田，利見大人。”">​</a></h3><p>大而得易簡之理，當成位乎天地之中，時舍而不受命，乾九二有焉。及夫化而聖矣，造而位天德矣，則富貴不足以言之。</p><h3 id="九三-君子終日乾乾-夕惕若-厲無咎。" tabindex="-1">九三，君子終日乾乾，夕惕若，厲無咎。 <a class="header-anchor" href="#九三-君子終日乾乾-夕惕若-厲無咎。" aria-label="Permalink to “九三，君子終日乾乾，夕惕若，厲無咎。”">​</a></h3><h3 id="九四-或躍在淵-無咎。" tabindex="-1">九四，或躍在淵，無咎。 <a class="header-anchor" href="#九四-或躍在淵-無咎。" aria-label="Permalink to “九四，或躍在淵，無咎。”">​</a></h3><p>四處陰，故曰在淵。</p><h3 id="九五-飛龍在天-利見大人。" tabindex="-1">九五，飛龍在天，利見大人。 <a class="header-anchor" href="#九五-飛龍在天-利見大人。" aria-label="Permalink to “九五，飛龍在天，利見大人。”">​</a></h3><h3 id="上九-亢龍有悔。" tabindex="-1">上九，亢龍有悔。 <a class="header-anchor" href="#上九-亢龍有悔。" aria-label="Permalink to “上九，亢龍有悔。”">​</a></h3><h3 id="用九-見群龍無首-吉。" tabindex="-1">用九，見群龍無首，吉。 <a class="header-anchor" href="#用九-見群龍無首-吉。" aria-label="Permalink to “用九，見群龍無首，吉。”">​</a></h3><p>［乾不居正位，是乾理自然，惟人推之使然耶!］</p><p>彖曰：大哉乾元，萬物資始，乃統天。雲行雨施，品物流形。大明終始，六位時成，時乘六龍以御天。乾道變化，各正性命，保合大和，乃利貞。首出庶物，萬國咸寧。</p><p>雲行雨施，散而無不之也，言乾發揮偏被於六十四卦，各使成象。變，言其著；化，言其漸。萬物皆始，故性命之各正。惟君子為能與時消息，順性命、躬天德而誠(之)行［之］也。精義時措，故能保合大和，健利且貞，孟子所謂終始條理，集大成於聖智者歟!易曰：“大明終始，六位時成，時乘六龍以御天。乾道變化，各正性命。保合大和，乃利貞”，其此之謂乎!“乾道變化，各正性命”，此謂六爻。言天道變化趨時者，六爻各隨時自正其性命，謂六位隨時正性命各有一道理，蓋為時各不同。</p><p>「首出庶物，萬國咸寧」不一則乖競。</p><p>象曰：天行健，君子以自強不息。</p><h3 id="潛龍勿用-陽在下也。-見龍在田-德施普也。-終日乾乾-反覆道也。" tabindex="-1">“潛龍勿用”，陽在下也。“見龍在田”，德施普也。“終日乾乾”，反覆道也。 <a class="header-anchor" href="#潛龍勿用-陽在下也。-見龍在田-德施普也。-終日乾乾-反覆道也。" aria-label="Permalink to ““潛龍勿用”，陽在下也。“見龍在田”，德施普也。“終日乾乾”，反覆道也。”">​</a></h3><p>道，行也，所行即是道。易亦言“天行健”，天道也。</p><h3 id="或躍在淵-進無咎也。" tabindex="-1">“或躍在淵”，進無咎也。 <a class="header-anchor" href="#或躍在淵-進無咎也。" aria-label="Permalink to ““或躍在淵”，進無咎也。”">​</a></h3><p>或躍進退皆可在淵者，性退也，故指其極而言也。</p><h3 id="飛龍在天-大人造也。" tabindex="-1">“飛龍在天”，大人造也。 <a class="header-anchor" href="#飛龍在天-大人造也。" aria-label="Permalink to ““飛龍在天”，大人造也。”">​</a></h3><p>乾之九五曰：“飛龍在天，利見大人”，乃大人造位天德，成性躋聖者爾。若夫受命首出，則所性不存焉，故不曰“位乎君位”而曰“位乎天德”，不曰“大人君矣”而曰大人造也”。 成性則躋聖而位天德。乾九二正位於內卦之中，有君德矣，而非上治也。九五言上治者，通言乎(聖人)［天］之德，聖人之性，［故］舍曰“君”而謂之“天”。見大人德與位之(者)［皆］造也。 至健而易，至順而簡，故其險其阻，不可階而升，不可(逸)［勉］而至。仲尼猶天，“九五飛龍在天”，其致一也。</p><h3 id="亢龍有悔-盈不可久也。" tabindex="-1">“亢龍有悔”，盈不可久也。 <a class="header-anchor" href="#亢龍有悔-盈不可久也。" aria-label="Permalink to ““亢龍有悔”，盈不可久也。”">​</a></h3><h3 id="用九-天德不可為首也。" tabindex="-1">“用九”，天德不可為首也。 <a class="header-anchor" href="#用九-天德不可為首也。" aria-label="Permalink to ““用九”，天德不可為首也。”">​</a></h3><p>文言</p><h3 id="元者-善之長也-亨者-嘉之會也-利者-義之和也-貞者-事之乾也。君子體仁足以長人-嘉會足以合禮-利物足以和義-貞固足以乾事。君子行此四德者-故曰-乾元亨利貞-。" tabindex="-1">元者，善之長也；亨者，嘉之會也，利者，義之和也；貞者，事之乾也。君子體仁足以長人，嘉會足以合禮，利物足以和義，貞固足以乾事。君子行此四德者，故曰“乾元亨利貞”。 <a class="header-anchor" href="#元者-善之長也-亨者-嘉之會也-利者-義之和也-貞者-事之乾也。君子體仁足以長人-嘉會足以合禮-利物足以和義-貞固足以乾事。君子行此四德者-故曰-乾元亨利貞-。" aria-label="Permalink to “元者，善之長也；亨者，嘉之會也，利者，義之和也；貞者，事之乾也。君子體仁足以長人，嘉會足以合禮，利物足以和義，貞固足以乾事。君子行此四德者，故曰“乾元亨利貞”。”">​</a></h3><p>仁統天下之善，禮嘉天下之會，義公天下之利，信一天下之動。</p><h3 id="初九曰-潛龍勿用-何謂也-子曰-龍德而隱者也。不易乎世-不成乎名-遁世無悶-不見是而無悶-樂則行之-憂則違之-確乎其不可拔-潛龍也。" tabindex="-1">初九曰“潛龍勿用”，何謂也？ 子曰：龍德而隱者也。不易乎世，不成乎名，遁世無悶，不見是而無悶，樂則行之，憂則違之，確乎其不可拔，潛龍也。 <a class="header-anchor" href="#初九曰-潛龍勿用-何謂也-子曰-龍德而隱者也。不易乎世-不成乎名-遁世無悶-不見是而無悶-樂則行之-憂則違之-確乎其不可拔-潛龍也。" aria-label="Permalink to “初九曰“潛龍勿用”，何謂也？ 子曰：龍德而隱者也。不易乎世，不成乎名，遁世無悶，不見是而無悶，樂則行之，憂則違之，確乎其不可拔，潛龍也。”">​</a></h3><p>孔子喜弟子之不仕，蓋為德未成則不可以仕，是行而未成者也。故潛勿用，龍德而未顯者也。不成名，不求聞也，養實而已，樂行憂違，不可與［無］德者語也。“用則行，舍則藏，惟我與爾有是夫!”顏子龍德而隱，故“遁世不見知而不悔”，(聖)與聖者同(能)。“遁世不見知而不悔”，聖人不為沽激之行以求時知，依乎中庸，人莫能知，以此自信，不知悔也。(大而得易簡之理，當成位乎天地之中，時舍而不受命，乾九二有焉。及夫化而聖矣，造而位天德矣，則富貴不足以言之。)“樂則行之，憂則違之”，主於［求］吾志而已，無所求於外，故善世溥化，龍德而見［者］也，［若］潛而未見，則為己而已，不暇及夫人者也。 孟子不得已而用潛龍者也，顏子不用潛龍者也。孟子主教，故須說“予豈好辯哉？予不得已也”。</p><h3 id="九二曰-見龍在田-利見大人-何謂也-子曰-龍德而正中者也。庸言之信-庸行之謹-閒邪存其誠-善世而不伐-德溥而化。易曰-見龍在田-利見大人-君德也。" tabindex="-1">九二曰“見龍在田，利見大人”，何謂也？ 子曰：龍德而正中者也。庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德溥而化。易曰“見龍在田，利見大人”，君德也。 <a class="header-anchor" href="#九二曰-見龍在田-利見大人-何謂也-子曰-龍德而正中者也。庸言之信-庸行之謹-閒邪存其誠-善世而不伐-德溥而化。易曰-見龍在田-利見大人-君德也。" aria-label="Permalink to “九二曰“見龍在田，利見大人”，何謂也？ 子曰：龍德而正中者也。庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德溥而化。易曰“見龍在田，利見大人”，君德也。”">​</a></h3><p>庸言庸行，蓋天下經德達道，大人之德施於是(者)溥矣，天下之文明於是著矣。然非窮變化之神以時措之宜，則或陷於非禮之禮，非義之義，此顏子所以求龍德(而)正中，乾乾進德，思處其極，未敢以方體之常安吾止也。 顏氏求龍德正中而未見其止，故擇中庸得一善則拳拳服膺，歡夫子［之］忽焉前後也。 乾三四，位過中重剛，時不可舍，庸言庸行不足以濟之，雖大人之盛有所不安。外趨變化，內正性命，故其危其疑，艱於見德者，時不得舍也。 九五，大人化矣，天德位矣，成性聖矣，故既曰“利見大人”，又曰“聖人作而萬物睹”。亢龍以位畫為言，若聖人則不失其正，何亢之有! 德溥而化，言化物也，以其善世即是化也。善其身，自化也；兼善天下，則是化物也；知化則是德。化，聖人自化也。化之況味，在學者未易見焉，但有此次序。</p><h3 id="九三曰-君子終日乾乾-夕惕若-厲無咎-何謂也-子曰-君子進德修業。忠信-所以進德也-修辭立其誠-所以居業也。知至至之-可與幾也-知終終之-可與存義也。是故居上位而不驕-在下位而不憂-故乾乾因其時而惕-雖危無咎矣。" tabindex="-1">九三曰“君子終日乾乾，夕惕若，厲無咎”，何謂也？ 子曰：君子進德修業。忠信，所以進德也；修辭立其誠，所以居業也。知至至之，可與幾也；知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。 <a class="header-anchor" href="#九三曰-君子終日乾乾-夕惕若-厲無咎-何謂也-子曰-君子進德修業。忠信-所以進德也-修辭立其誠-所以居業也。知至至之-可與幾也-知終終之-可與存義也。是故居上位而不驕-在下位而不憂-故乾乾因其時而惕-雖危無咎矣。" aria-label="Permalink to “九三曰“君子終日乾乾，夕惕若，厲無咎”，何謂也？ 子曰：君子進德修業。忠信，所以進德也；修辭立其誠，所以居業也。知至至之，可與幾也；知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。”">​</a></h3><p>乾九三修辭立誠，非繼日待旦如周公，不足以終其業。 忠信所以進德，學者止是一誠意耳，若不忠信，如何進德!不驕，德當至也；不憂，業當終也。 適在不安之位，故曰因其時。 求致用者，幾不可緩；將進德者，涉義必精；此君子所以立多兇多懼之地，乾乾德業，不少懈 於趨時也。知至，極盡其所知也。</p><h3 id="九四曰-或躍在淵無咎-何謂也-子曰-上下無常-非為邪也-進退無恆-非離群也-君子進德修業-欲及時也-故無咎。" tabindex="-1">九四曰“或躍在淵無咎”，何謂也？ 子曰：上下無常，非為邪也；進退無恆，非離群也；君子進德修業，欲及時也，故無咎。 <a class="header-anchor" href="#九四曰-或躍在淵無咎-何謂也-子曰-上下無常-非為邪也-進退無恆-非離群也-君子進德修業-欲及時也-故無咎。" aria-label="Permalink to “九四曰“或躍在淵無咎”，何謂也？ 子曰：上下無常，非為邪也；進退無恆，非離群也；君子進德修業，欲及時也，故無咎。”">​</a></h3><p>以陽居陰，故曰“在淵”；位非所安，故或以躍。德非為邪，故進退上下，惟義所適，惟時所合，故曰“欲及時也”。能如此擇義，則無咎也。 九四以陽居陰，故曰在淵，能不忘於躍，乃可免咎。“非為邪也”，終其義也。</p><h3 id="九五曰-飛龍在天-利見大人-何謂也-子曰-同聲相應-同氣相求-水流溼-火就燥-雲從龍-風從虎-聖人作而萬物睹。本乎天者親上-本乎地者親下-則各從其類也。" tabindex="-1">九五曰“飛龍在天，利見大人”，何謂也？ 子曰：同聲相應，同氣相求，水流溼，火就燥，雲從龍，風從虎，聖人作而萬物睹。本乎天者親上，本乎地者親下，則各從其類也。 <a class="header-anchor" href="#九五曰-飛龍在天-利見大人-何謂也-子曰-同聲相應-同氣相求-水流溼-火就燥-雲從龍-風從虎-聖人作而萬物睹。本乎天者親上-本乎地者親下-則各從其類也。" aria-label="Permalink to “九五曰“飛龍在天，利見大人”，何謂也？ 子曰：同聲相應，同氣相求，水流溼，火就燥，雲從龍，風從虎，聖人作而萬物睹。本乎天者親上，本乎地者親下，則各從其類也。”">​</a></h3><p>穀神能象其聲而應之，非謂能報以律呂之變也，猶卜筮叩以是言則報以是物而已，易［所］謂“同聲相應”是也。王弼謂“命呂者律”，語聲之變，非此之謂也。 聖人作，萬物睹，故利見大人。 本乎天者親上，本乎地者親下，此一章止為飛龍在天而發。龍虎水火之喻，蓋明各逐一類去，本在上者卻上去，本在下者卻逐下。德性本得乎天者今覆在天，是各從其類也。</p><h3 id="上九曰-亢龍有悔-何謂也-子曰-貴而無位-高而無民-賢人在下位而無輔-是以動而有悔也。" tabindex="-1">上九曰“亢龍有悔”，何謂也？ 子曰：貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。 <a class="header-anchor" href="#上九曰-亢龍有悔-何謂也-子曰-貴而無位-高而無民-賢人在下位而無輔-是以動而有悔也。" aria-label="Permalink to “上九曰“亢龍有悔”，何謂也？ 子曰：貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。”">​</a></h3><p>亢而自喪之也。</p><h3 id="潛龍勿用-下也。-見龍在田-時舍也。-終日乾乾-行事也。-或躍在淵-自試也。-飛龍在天-上治也。-亢龍有悔-窮之災也。-乾元用九-天下治也。" tabindex="-1">“潛龍勿用”，下也。“見龍在田”，時舍也。“終日乾乾”，行事也。“或躍在淵”，自試也。“飛龍在天”，上治也。“亢龍有悔”，窮之災也。“乾元用九”，天下治也。 <a class="header-anchor" href="#潛龍勿用-下也。-見龍在田-時舍也。-終日乾乾-行事也。-或躍在淵-自試也。-飛龍在天-上治也。-亢龍有悔-窮之災也。-乾元用九-天下治也。" aria-label="Permalink to ““潛龍勿用”，下也。“見龍在田”，時舍也。“終日乾乾”，行事也。“或躍在淵”，自試也。“飛龍在天”，上治也。“亢龍有悔”，窮之災也。“乾元用九”，天下治也。”">​</a></h3><p>居大中安止之地，至於三四則不得所安也。 聖人神其德，不私其身，故乾乾自強，所以成之於天耳。</p><h3 id="潛龍勿用-陽氣潛藏。-見龍在田-天下文明。-終日乾乾-與時偕行。-或躍在淵-乾道乃革。-飛龍在天-乃位乎天德。-亢龍有悔-與時偕極。" tabindex="-1">“潛龍勿用”，陽氣潛藏。“見龍在田”，天下文明。“終日乾乾”，與時偕行。“或躍在淵”，乾道乃革。“飛龍在天”，乃位乎天德。“亢龍有悔”，與時偕極。 <a class="header-anchor" href="#潛龍勿用-陽氣潛藏。-見龍在田-天下文明。-終日乾乾-與時偕行。-或躍在淵-乾道乃革。-飛龍在天-乃位乎天德。-亢龍有悔-與時偕極。" aria-label="Permalink to ““潛龍勿用”，陽氣潛藏。“見龍在田”，天下文明。“終日乾乾”，與時偕行。“或躍在淵”，乾道乃革。“飛龍在天”，乃位乎天德。“亢龍有悔”，與時偕極。”">​</a></h3><p>顏子未成性，是為潛龍，亦未肯止於見龍，蓋以其德其時則須當潛。顏子與孟子時異，顏子有孔子在，可以不顯，孟子則處師道，亦是已老，故不得不顯耳。九二、九三、九四至九，皆是時也。</p><p>九四曰：“上下無常，非為邪也。進退無恆，非離群也。君子進德修業，欲及時也。” 此時可上可下，可進可退，“非為邪也”，即是直也。天道不越乎直，直方大則不須習，行之自無不利。非為邪，則是陟降庭止也。進德修業欲及時，即是無然畔援，無然歆羨，誕先登於岸也，言無畔去，亦無援引，亦無歆向，亦無羨而不為，誕知登於岸耳。岸，所處地位也。此與進無咎同意，惟志在位天德而已。位天德，大人成性也。</p><p>九三、九四大體相似，此二時處危難之大，聖人則事天愛民，不恤其他，誕先登於岸。九五“大人造也”，造，成就也，或謂造為至義亦可。大人成性則聖也化，化則純是天德也。聖猶天也，故不可階而升。聖人之教，未嘗以性化責人，若大人則學可至也。位天德則神，神則天也，故不可以神屬人而言。莊子言神人，不識義理也；又謂至人真人，其辭險窄，皆無可取。孟子六等，至於神則不可言人也。</p><p>上九亢龍，緣卦畫而言，須分初終，終則自是亢極。言君位則易有極之理，聖人之分則安有過亢!</p><p>易雖以六爻為次序而言，如此則是以典要求也。乾初以其在初處下，況聖修而未成者可也。上以居極位畫為亢，聖人則何亢之有! 若二與三皆大人之事，非謂四勝於三，三勝於二，五又勝於四，如此則是聖可階也。三四與二，皆言所過之時。二之時平和，見龍在田者則是可止之處也。時舍，時止也，以時之和平，故利見不至於有害。三四則皆時為危難，又重剛，又不中，至九五則是聖人極致處，不論時也。飛龍在天，況聖人之至若天之不可階而升也。</p><p>大人與聖人自是一節妙處。精義入神，以致用也；利用安身，以崇德也。” 以理計之，如崇德之事尚可勉勉修而至，若大人以上事則無修，故曰“過此以往，未之或知”，言不可得而知也，直待己實到窮神知化，是德之極盛處也。然而人為者不過大人之事，但德盛處惟己知之，“默而成之，不言而信，不怒而威”，如此方是成就吾之所行大人之事而已。</p><p>故於此爻卻說，“大人者與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶”，如此則是全與天地一體，然不過是大人之事，惟是心化也。故嘗謂大可為也，大而化不可為也，在熟而已。蓋大人之事，修而可至，化則不可加功，加功則是助長也，要在乎仁熟而已。</p><p>然而至於大以上自是住不得，言在熟極有意。大與聖難於分別，大以上之事，如禹、稷、皋陶輩猶未必能知，然須當皆謂之聖人，蓋為所以接人者與聖同，但己自知不足，不肯自以為聖。如禹之德，斯可謂之大矣，其心以天下為己任，規模如此；又克己若禹，則與聖人直無間別，孔子亦謂“禹於吾無間然矣”，久則須至堯舜。</p><p>有人於此，敦厚君子，無少異聖人之言行，然其心與真仲尼須自覺有殊，在他人則安能分別! 當時至有以子貢為賢於仲尼者，惟子貢則自知之。人能以大為心，常以聖人之規模為己任，久於其道，則須化而至聖人，理之必然，如此，其大即是天也。</p><p>又要細密處行之，並暗隙不欺，若心化處則誠未易至。孔子猶自謂“若聖與仁則吾豈敢”，儻曰“吾聖矣”，則人亦誰能知! 故曰“知我者其天乎”。然則必九五言“乃位乎天德”，蓋是成聖實到也；不言“首出”，所性不存焉，其實天地也，不曰“天地”而曰“天德”，言德則德位皆造，故曰“大人造也”，至此乃是大人之事畢矣。</p><p>五，乾之極盛處，故以此當聖人之成德，言“乃位”即是實到為己有也。若田思慮勉勉而至者，止可言知，不可言位也，“乃位”則實在其所矣。大抵語勉勉者則是大人之分也，勉勉則猶或有退，少不勉勉斯退矣，所以須學問。進德修業，欲成性也，成性則從心皆天也。所以成性則謂之聖者，如夷之清，惠之和，不必勉勉。彼一節而成性，若聖人則於大以成性。</p><p>剛健故應乎天，文明故時行。乾二五皆正中之德，五則曰“大人造也”，又曰“聖人作而萬物睹”，大人而升聖乃位乎天德也。不言“帝王”而言“天德”，位不足道也，所性不存焉。潛龍自是聖人之德備具，但未發見。</p><p>見龍成性，至飛龍則位天德。</p><h3 id="乾元用九-乃見天則。乾元者-始而亨者也-利貞者-性情也。" tabindex="-1">“乾元用九”，乃見天則。乾元者，始而亨者也，利貞者，性情也。 <a class="header-anchor" href="#乾元用九-乃見天則。乾元者-始而亨者也-利貞者-性情也。" aria-label="Permalink to ““乾元用九”，乃見天則。乾元者，始而亨者也，利貞者，性情也。”">​</a></h3><p>“利貞者，性情也”，以利解性，以貞解情。利，流通之義，貞者實也；利，快利也，貞，實也；利，性也，貞，情也。情盡在氣之外，其發見莫非性之自然，快利儘性，所以神也。情則是實事，喜怒哀樂之謂也，欲喜者如此喜之，欲怒者如此怒之，欲哀欲樂者如此樂之哀之，莫非性中發出實事也。</p><h3 id="乾始能以美利利天下-不言所利-大矣哉-大哉乾乎-剛健中正-純粹精也-六爻發揮-旁通情也" tabindex="-1">乾始能以美利利天下，不言所利，大矣哉!大哉乾乎!剛健中正，純粹精也；六爻發揮，旁通情也； <a class="header-anchor" href="#乾始能以美利利天下-不言所利-大矣哉-大哉乾乎-剛健中正-純粹精也-六爻發揮-旁通情也" aria-label="Permalink to “乾始能以美利利天下，不言所利，大矣哉!大哉乾乎!剛健中正，純粹精也；六爻發揮，旁通情也；”">​</a></h3><p>“剛健中正”，中爻之德。“剛健中正，純粹精也”，主以中正為精也。“六爻發揮”，言時各異。“旁通情也”，情猶言用也。六爻擬議，各正性命，(其)［故］乾德旁通，不失太和而(和)［利］且貞也。</p><h3 id="時乘六龍-以御天也-雲行雨施-天下平也。君子以成德為行-日可見之行也。" tabindex="-1">時乘六龍，以御天也；雲行雨施，天下平也。君子以成德為行，日可見之行也。 <a class="header-anchor" href="#時乘六龍-以御天也-雲行雨施-天下平也。君子以成德為行-日可見之行也。" aria-label="Permalink to “時乘六龍，以御天也；雲行雨施，天下平也。君子以成德為行，日可見之行也。”">​</a></h3><p>“成德為行”，德成自信而不疑，所以日見於外可也。</p><h3 id="潛之為言也-隱而未見-行而未成-是以君子弗用也。君子學以聚之-問以辯之-寬以居之-仁以行之。" tabindex="-1">潛之為言也，隱而未見，行而未成，是以君子弗用也。君子學以聚之，問以辯之，寬以居之，仁以行之。 <a class="header-anchor" href="#潛之為言也-隱而未見-行而未成-是以君子弗用也。君子學以聚之-問以辯之-寬以居之-仁以行之。" aria-label="Permalink to “潛之為言也，隱而未見，行而未成，是以君子弗用也。君子學以聚之，問以辯之，寬以居之，仁以行之。”">​</a></h3><p>君子之道，成身成性以為功者也，未至於聖，皆行未成之地耳。顏子之徒，隱而未見，行而未成，故曰“吾聞其語矣，未見其人也”。“龍德而隱”，聖修而未成者也，非如學者之未成。凡言龍，喻聖也，若顏子可以當之，雖伯夷之學猶不可言龍。龍即聖人之德，顏子則術正也。</p><h3 id="易曰-見龍在田-利見大人-君德也。九三重剛而不中-上不在天-下不在田-故乾乾因其時而惕-雖危無咎矣。九四重剛而不中-上不在天-下不在田-中不在人-故或之-或之者-疑之也-故無咎。" tabindex="-1">易曰：“見龍在田，利見大人”，君德也。九三重剛而不中，上不在天，下不在田，故乾乾因其時而惕，雖危無咎矣。九四重剛而不中，上不在天，下不在田，中不在人，故或之；或之者，疑之也，故無咎。 <a class="header-anchor" href="#易曰-見龍在田-利見大人-君德也。九三重剛而不中-上不在天-下不在田-故乾乾因其時而惕-雖危無咎矣。九四重剛而不中-上不在天-下不在田-中不在人-故或之-或之者-疑之也-故無咎。" aria-label="Permalink to “易曰：“見龍在田，利見大人”，君德也。九三重剛而不中，上不在天，下不在田，故乾乾因其時而惕，雖危無咎矣。九四重剛而不中，上不在天，下不在田，中不在人，故或之；或之者，疑之也，故無咎。”">​</a></h3><p>此以六畫分三才也。以下二畫屬地，則四遠於地，故言中不在人；若三則止言不在天，在田而已。</p><h3 id="夫大人者-與天地合其德-與日月合其明-與四時合其序-與鬼神合其吉凶-先天而天弗違-後天而奉天時。天且弗違-而況於人乎-況於鬼神乎-亢之為言也-知進而不知退-知存而不知亡-知得而不知喪。其唯聖人乎-知進退存亡而不失其正者-其唯聖人乎" tabindex="-1">夫大人者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶，先天而天弗違，後天而奉天時。天且弗違，而況於人乎!況於鬼神乎!亢之為言也，知進而不知退，知存而不知亡，知得而不知喪。其唯聖人乎!知進退存亡而不失其正者，其唯聖人乎! <a class="header-anchor" href="#夫大人者-與天地合其德-與日月合其明-與四時合其序-與鬼神合其吉凶-先天而天弗違-後天而奉天時。天且弗違-而況於人乎-況於鬼神乎-亢之為言也-知進而不知退-知存而不知亡-知得而不知喪。其唯聖人乎-知進退存亡而不失其正者-其唯聖人乎" aria-label="Permalink to “夫大人者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶，先天而天弗違，後天而奉天時。天且弗違，而況於人乎!況於鬼神乎!亢之為言也，知進而不知退，知存而不知亡，知得而不知喪。其唯聖人乎!知進退存亡而不失其正者，其唯聖人乎!”">​</a></h3><p>浩然無間則天地合德，照無偏系則日月合明，天地同流則四時合序，酬酢不倚則鬼神合吉凶。 天地合德，日月合明，然後能無方無體，然後無我，先後天而不違，順至理以推行，知無不合也。 雖然，得聖人之任；皆可勉而至，猶不害於未化爾。</p>',67)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
